mapper.select:
select u.id as id, u.nickname as nickname, u.username as username, u.mobile as mobile, u.nickname as nickname, u.gender as gender, u.age as age, u.avatar as avatar, u.is_disabled as isDisabled, u.create_time as createTime, u.update_time as updateTime, u.last_login_time as lastLoginTime, u.last_login_ip as lastLoginIp, r.id as roleId, r.code as roleCode, r.name as roleName from acl_user u left join acl_user_role ur on u.id = ur.uid left join acl_role r on ur.role_id = r.id where u.is_deleted = 0 and r.code != 0
and ${ew.sqlSegment}
order by r.code asc , u.create_time desc
